/**
 * Pure JavaScript QRCode Generator (Minimal standalone version for ClipDown Extension)
 * Based on QRCode.js (MIT License)
 */
(function(global) {
    function QR8bitByte(data) {
        this.mode = 4;
        this.data = data;
    }
    QR8bitByte.prototype = {
        getLength: function() { return this.data.length; },
        write: function(buffer) {
            for (var i = 0; i < this.data.length; i++) {
                buffer.put(this.data.charCodeAt(i), 8);
            }
        }
    };

    var QRCodeLimitLength = [
        [17, 14, 11, 7], [32, 26, 20, 14], [53, 42, 32, 24], [78, 62, 46, 34],
        [106, 84, 60, 44], [134, 106, 74, 58], [154, 122, 86, 64], [192, 152, 108, 84],
        [230, 180, 130, 98], [271, 213, 151, 119], [321, 251, 177, 137], [367, 287, 203, 155],
        [425, 331, 241, 177], [458, 362, 258, 194], [520, 412, 292, 220], [586, 464, 322, 250],
        [644, 514, 364, 280], [718, 570, 402, 310], [792, 628, 442, 338], [858, 684, 482, 382]
    ];

    function QRBitBuffer() {
        this.buffer = [];
        this.length = 0;
    }
    QRBitBuffer.prototype = {
        get: function(index) {
            var bufIndex = Math.floor(index / 8);
            return ((this.buffer[bufIndex] >>> (7 - index % 8)) & 1) == 1;
        },
        put: function(num, length) {
            for (var i = 0; i < length; i++) {
                this.putBit(((num >>> (length - i - 1)) & 1) == 1);
            }
        },
        putBit: function(bit) {
            var bufIndex = Math.floor(this.length / 8);
            if (this.buffer.length <= bufIndex) {
                this.buffer.push(0);
            }
            if (bit) {
                this.buffer[bufIndex] |= (0x80 >>> (this.length % 8));
            }
            this.length++;
        }
    };

    function QRCodeModel(typeNumber, errorCorrectLevel) {
        this.typeNumber = typeNumber;
        this.errorCorrectLevel = errorCorrectLevel;
        this.modules = null;
        this.moduleCount = 0;
        this.dataList = [];
    }
    QRCodeModel.prototype = {
        addData: function(data) {
            var newData = new QR8bitByte(data);
            this.dataList.push(newData);
        },
        isDark: function(row, col) {
            if (row < 0 || this.moduleCount <= row || col < 0 || this.moduleCount <= col) {
                throw new Error(row + "," + col);
            }
            return this.modules[row][col];
        },
        getModuleCount: function() { return this.moduleCount; },
        make: function() {
            if (this.typeNumber < 1) {
                var typeNumber = 1;
                for (; typeNumber < 40; typeNumber++) {
                    var limit = QRCodeLimitLength[typeNumber - 1][this.errorCorrectLevel];
                    var length = 0;
                    for (var i = 0; i < this.dataList.length; i++) {
                        length += this.dataList[i].getLength();
                    }
                    if (length <= limit) break;
                }
                this.typeNumber = typeNumber;
            }
            this.makeImpl(false, this.getBestMaskPattern());
        },
        makeImpl: function(test, maskPattern) {
            this.moduleCount = this.typeNumber * 4 + 17;
            this.modules = new Array(this.moduleCount);
            for (var row = 0; row < this.moduleCount; row++) {
                this.modules[row] = new Array(this.moduleCount);
                for (var col = 0; col < this.moduleCount; col++) {
                    this.modules[row][col] = null;
                }
            }
            this.setupPositionProbePattern(0, 0);
            this.setupPositionProbePattern(this.moduleCount - 7, 0);
            this.setupPositionProbePattern(0, this.moduleCount - 7);
            this.setupTimingPattern();
            this.setupTypeInfo(test, maskPattern);
            if (this.typeNumber >= 7) {
                this.setupTypeNumber(test);
            }
            var totalDataCount = this.dataList.length > 0 ? this.dataList[0].getLength() : 0;
            var buffer = new QRBitBuffer();
            for (var i = 0; i < this.dataList.length; i++) {
                var data = this.dataList[i];
                buffer.put(data.mode, 4);
                buffer.put(data.getLength(), 8);
                data.write(buffer);
            }
            buffer.put(0, 4);
            while ((buffer.length % 8) != 0) {
                buffer.putBit(false);
            }
            var padBytes = [0xEC, 0x11];
            var padIndex = 0;
            var maxBits = this.moduleCount * this.moduleCount;
            while (buffer.length + 8 <= maxBits) {
                buffer.put(padBytes[padIndex % 2], 8);
                padIndex++;
            }
            this.mapData(buffer, maskPattern);
        },
        setupPositionProbePattern: function(row, col) {
            for (var r = -1; r <= 7; r++) {
                if (row + r <= -1 || this.moduleCount <= row + r) continue;
                for (var c = -1; c <= 7; c++) {
                    if (col + c <= -1 || this.moduleCount <= col + c) continue;
                    if ((0 <= r && r <= 6 && (c == 0 || c == 6)) ||
                        (0 <= c && c <= 6 && (r == 0 || r == 6)) ||
                        (2 <= r && r <= 4 && 2 <= c && c <= 4)) {
                        this.modules[row + r][col + c] = true;
                    } else {
                        this.modules[row + r][col + c] = false;
                    }
                }
            }
        },
        setupTimingPattern: function() {
            for (var r = 8; r < this.moduleCount - 8; r++) {
                if (this.modules[r][6] !== null) continue;
                this.modules[r][6] = (r % 2 == 0);
            }
            for (var c = 8; c < this.moduleCount - 8; c++) {
                if (this.modules[6][c] !== null) continue;
                this.modules[6][c] = (c % 2 == 0);
            }
        },
        setupTypeNumber: function(test) {},
        setupTypeInfo: function(test, maskPattern) {
            var data = (this.errorCorrectLevel << 3) | maskPattern;
            var bits = (data << 10);
            for (var i = 0; i < 15; i++) {
                var mod = ((bits >> i) & 1) == 1;
                if (i < 6) this.modules[i][8] = mod;
                else if (i < 8) this.modules[i + 1][8] = mod;
                else this.modules[this.moduleCount - 15 + i][8] = mod;

                if (i < 8) this.modules[8][this.moduleCount - i - 1] = mod;
                else if (i < 9) this.modules[8][15 - i - 1 + 1] = mod;
                else this.modules[8][15 - i - 1] = mod;
            }
            this.modules[this.moduleCount - 8][8] = true;
        },
        mapData: function(data, maskPattern) {
            var inc = -1;
            var row = this.moduleCount - 1;
            var bitIndex = 0;
            var byteIndex = 0;
            for (var col = this.moduleCount - 1; col > 0; col -= 2) {
                if (col == 6) col--;
                while (true) {
                    for (var c = 0; c < 2; c++) {
                        if (this.modules[row][col - c] === null) {
                            var dark = false;
                            if (byteIndex < data.length) {
                                dark = data.get(byteIndex);
                                byteIndex++;
                            }
                            var mask = ((row + col - c) % 2 == 0);
                            if (mask) dark = !dark;
                            this.modules[row][col - c] = dark;
                        }
                    }
                    row += inc;
                    if (row < 0 || this.moduleCount <= row) {
                        row -= inc;
                        inc = -inc;
                        break;
                    }
                }
            }
        },
        getBestMaskPattern: function() { return 0; }
    };

    function QRCode(targetElement, options) {
        if (typeof options === 'string') options = { text: options };
        options = options || {};
        this._el = typeof targetElement === 'string' ? document.getElementById(targetElement) : targetElement;
        this._width = options.width || 200;
        this._height = options.height || 200;
        this._colorDark = options.colorDark || '#000000';
        this._colorLight = options.colorLight || '#ffffff';
        if (options.text) this.makeCode(options.text);
    }

    QRCode.prototype.makeCode = function(text) {
        var qr = new QRCodeModel(0, 1);
        qr.addData(text);
        qr.make();
        this._el.innerHTML = '';
        var canvas = document.createElement('canvas');
        canvas.width = this._width;
        canvas.height = this._height;
        var ctx = canvas.getContext('2d');
        var count = qr.getModuleCount();
        var tileW = this._width / count;
        var tileH = this._height / count;
        for (var row = 0; row < count; row++) {
            for (var col = 0; col < count; col++) {
                ctx.fillStyle = qr.isDark(row, col) ? this._colorDark : this._colorLight;
                ctx.fillRect(Math.round(col * tileW), Math.round(row * tileH), Math.ceil(tileW), Math.ceil(tileH));
            }
        }
        this._el.appendChild(canvas);
    };

    global.QRCode = QRCode;
})(typeof window !== 'undefined' ? window : this);
